export default function ClientLogos() {
	const sectionRef = useRef<HTMLElement | null>(null);
	const viewportRef = useRef<HTMLDivElement | null>(null);
	const trackRef = useRef<HTMLDivElement | null>(null);
	const firstSetRef = useRef<HTMLDivElement | null>(null);
	const offsetRef = useRef(0);
	const setWidthRef = useRef(0);
	const velocityRef = useRef(BASE_SPEED);
	const isHoveringRef = useRef(false);
	const isDraggingRef = useRef(false);
	const pointerIdRef = useRef<number | null>(null);
	const pointerStartXRef = useRef(0);
	const lastPointerXRef = useRef(0);
	const lastPointerTimeRef = useRef(0);
	const prefersReducedMotionRef = useRef(false);

	const logosWithAsset = LOGOS.filter(
		(logo): logo is LogoItem & { svg: string } => Boolean(logo.svg)
	);
	const duplicatedLogos: Array<LogoItem & { svg: string }> = [...logosWithAsset, ...logosWithAsset];

	useEffect(() => {
		const viewport = viewportRef.current;

		const measure = () => {
			setWidthRef.current = firstSetRef.current?.offsetWidth ?? 0;
		};

		measure();

		const observer = new ResizeObserver(measure);
		if (firstSetRef.current) {
			observer.observe(firstSetRef.current);
		}

		const reduceMotionQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
		prefersReducedMotionRef.current = reduceMotionQuery.matches;
		const onMotionPreferenceChange = (event: MediaQueryListEvent) => {
			prefersReducedMotionRef.current = event.matches;
		};
		reduceMotionQuery.addEventListener("change", onMotionPreferenceChange);

		const wrapOffset = (value: number) => {
			const width = setWidthRef.current;
			if (width <= 0) {
				return value;
			}

			let wrapped = value % width;
			if (wrapped < 0) {
				wrapped += width;
			}
			return wrapped;
		};

		const onPointerDown = (event: PointerEvent) => {
			if (!viewport) {
				return;
			}

			if (event.pointerType === "mouse" && event.button !== 0) {
				return;
			}

			pointerIdRef.current = event.pointerId;
			pointerStartXRef.current = event.clientX;
			velocityRef.current = 0;
			lastPointerXRef.current = event.clientX;
			lastPointerTimeRef.current = performance.now();
		};

		const onPointerMove = (event: PointerEvent) => {
			if (pointerIdRef.current !== event.pointerId) {
				return;
			}

			const dragStartThreshold = getDragStartThreshold(event.pointerType);

			if (!isDraggingRef.current) {
				const moved = Math.abs(event.clientX - pointerStartXRef.current);
				if (moved < dragStartThreshold) {
					return;
				}

				isDraggingRef.current = true;
				sectionRef.current?.classList.add("is-logo-dragging");
				if (viewport && !viewport.hasPointerCapture(event.pointerId)) {
					viewport.setPointerCapture(event.pointerId);
				}
			}

			const now = performance.now();
			const dx = event.clientX - lastPointerXRef.current;
			const dtMs = Math.max(8, now - lastPointerTimeRef.current);
			const dt = dtMs / 1000;

			offsetRef.current = wrapOffset(offsetRef.current - dx);
			applyTrackTransform(trackRef.current, offsetRef.current);
			const instantaneousVelocity = -dx / dt;
			velocityRef.current = clamp(
				velocityRef.current * 0.58 + instantaneousVelocity * 0.42,
				-MAX_ABS_VELOCITY,
				MAX_ABS_VELOCITY
			);

			lastPointerXRef.current = event.clientX;
			lastPointerTimeRef.current = now;
		};

		const onWheel = (event: WheelEvent) => {
			const width = setWidthRef.current;
			if (width <= 0 || event.ctrlKey) {
				return;
			}

			const horizontalIntent = Math.abs(event.deltaX) > Math.abs(event.deltaY) * 1.15 || event.shiftKey;
			if (!horizontalIntent) {
				return;
			}

			const wheelDelta = event.shiftKey && Math.abs(event.deltaX) < 0.01 ? event.deltaY : event.deltaX;
			if (Math.abs(wheelDelta) < 0.1) {
				return;
			}

			event.preventDefault();
			offsetRef.current = wrapOffset(offsetRef.current + wheelDelta * 0.95);
			velocityRef.current = clamp(wheelDelta * 1.45, -MAX_ABS_VELOCITY, MAX_ABS_VELOCITY);
		};

		const endDrag = (event: PointerEvent) => {
			if (pointerIdRef.current !== event.pointerId) {
				return;
			}

			if (isDraggingRef.current && viewport && viewport.hasPointerCapture(event.pointerId)) {
				viewport.releasePointerCapture(event.pointerId);
			}

			if (isDraggingRef.current) {
				const releaseTarget = prefersReducedMotionRef.current
					? 0
					: isHoveringRef.current
						? HOVER_SLOW_SPEED
						: BASE_SPEED;
				velocityRef.current = clamp(
					velocityRef.current * 0.52 + releaseTarget * 0.48,
					-920,
					920
				);
			}

			isDraggingRef.current = false;
			pointerIdRef.current = null;
			sectionRef.current?.classList.remove("is-logo-dragging");
		};

		const onMouseEnter = () => {
			isHoveringRef.current = true;
		};

		const onMouseLeave = () => {
			isHoveringRef.current = false;
		};

		if (viewport) {
			viewport.addEventListener("pointerdown", onPointerDown);
			viewport.addEventListener("pointermove", onPointerMove);
			viewport.addEventListener("pointerup", endDrag);
			viewport.addEventListener("pointercancel", endDrag);
			viewport.addEventListener("mouseenter", onMouseEnter);
			viewport.addEventListener("mouseleave", onMouseLeave);
			viewport.addEventListener("wheel", onWheel, { passive: false });
		}

		let rafId = 0;
		let lastTime = performance.now();

		const animate = (time: number) => {
			const dt = Math.min((time - lastTime) / 1000, 0.05);
			lastTime = time;

			const targetSpeed = prefersReducedMotionRef.current
				? 0
				: isHoveringRef.current
					? HOVER_SLOW_SPEED
					: BASE_SPEED;

			if (!isDraggingRef.current) {
				const damping = Math.exp(-dt * 1.6);
				velocityRef.current = clamp(
					velocityRef.current * damping + targetSpeed * (1 - damping),
					-MAX_ABS_VELOCITY,
					MAX_ABS_VELOCITY
				);
			}

			const width = setWidthRef.current;
			if (trackRef.current && width > 0) {
				if (!isDraggingRef.current) {
					offsetRef.current = wrapOffset(offsetRef.current + velocityRef.current * dt);
				}

				applyTrackTransform(trackRef.current, offsetRef.current);
			}

			rafId = window.requestAnimationFrame(animate);
		};

		rafId = window.requestAnimationFrame(animate);

		return () => {
			window.cancelAnimationFrame(rafId);
			observer.disconnect();
			reduceMotionQuery.removeEventListener("change", onMotionPreferenceChange);
			sectionRef.current?.classList.remove("is-logo-dragging");

			if (viewport) {
				viewport.removeEventListener("pointerdown", onPointerDown);
				viewport.removeEventListener("pointermove", onPointerMove);
				viewport.removeEventListener("pointerup", endDrag);
				viewport.removeEventListener("pointercancel", endDrag);
				viewport.removeEventListener("mouseenter", onMouseEnter);
				viewport.removeEventListener("mouseleave", onMouseLeave);
				viewport.removeEventListener("wheel", onWheel);
			}
		};
	}, []);

	return (
		<section ref={sectionRef} className="client-logo-section" data-name="section-collaborators">
			<style>{`
				.client-logo-section {
					position: relative;
					width: 100%;
					overflow: hidden;
					height: 240px;
					background: #090909;
				}

				.client-logo-stage {
					position: relative;
					width: 100%;
					height: 100%;
					overflow: hidden;
					background: radial-gradient(120% 90% at 50% 50%, rgba(255, 255, 255, 0.025), rgba(255, 255, 255, 0));
				}

				.client-logo-mask {
					position: absolute;
					inset: 0;
					pointer-events: none;
					background: linear-gradient(
						90deg,
						rgba(9, 9, 9, 1) 0%,
						rgba(9, 9, 9, 0) 10%,
						rgba(9, 9, 9, 0) 90%,
						rgba(9, 9, 9, 1) 100%
					);
				}

				.client-logo-dither {
					position: absolute;
					inset: 0;
					pointer-events: none;
					opacity: 0.02;
					background-image:
						radial-gradient(circle at 25% 25%, rgba(255, 255, 255, 0.28) 0.6px, transparent 0.7px),
						radial-gradient(circle at 75% 75%, rgba(255, 255, 255, 0.24) 0.6px, transparent 0.7px);
					background-size: 5px 5px;
					mix-blend-mode: soft-light;
				}

				.client-logo-noise {
					position: absolute;
					inset: -40%;
					pointer-events: none;
					opacity: 0.016;
					background-image:
						radial-gradient(circle at 30% 30%, rgba(255, 255, 255, 0.42) 0.7px, transparent 0.8px),
						radial-gradient(circle at 70% 70%, rgba(255, 255, 255, 0.32) 0.6px, transparent 0.8px);
					background-size: 3px 3px, 4px 4px;
					mix-blend-mode: soft-light;
					animation: client-logo-film-noise 1200ms steps(3, end) infinite;
				}

				.client-logo-track {
					position: relative;
					display: flex;
					align-items: center;
					width: max-content;
					will-change: transform;
					gap: 0;
					padding: 0 clamp(16px, 4vw, 48px);
				}

				.client-logo-viewport {
					height: 100%;
					display: flex;
					align-items: center;
					overflow: hidden;
					touch-action: pan-y;
					user-select: none;
					-webkit-user-select: none;
					cursor: grab;
				}

				.client-logo-set {
					display: flex;
					align-items: center;
					gap: 0;
					flex: 0 0 auto;
				}

				.client-logo-item {
					flex: 0 0 auto;
					height: var(--logo-height, 64px);
					display: flex;
					align-items: center;
					justify-content: center;
					padding-right: 128px;
					opacity: 0.86;
					cursor: grab;
				}

				.client-logo-section.is-logo-dragging .client-logo-viewport,
				.client-logo-section.is-logo-dragging .client-logo-track,
				.client-logo-section.is-logo-dragging .client-logo-item {
					cursor: grabbing !important;
				}

				.client-logo-item svg {
					width: auto;
					height: var(--logo-height, 64px);
					max-height: var(--logo-height, 64px);
					object-fit: contain;
					filter: brightness(1.03) contrast(1.05);
					transform: scale(var(--logo-scale, 1));
					transform-origin: center;
				}

				@keyframes client-logo-film-noise {
					0% { transform: translate3d(0, 0, 0); }
					25% { transform: translate3d(2%, -1%, 0); }
					50% { transform: translate3d(-1%, 1.6%, 0); }
					75% { transform: translate3d(1.4%, 0.8%, 0); }
					100% { transform: translate3d(0, 0, 0); }
				}

				@media (max-width: 768px) {
					.client-logo-section {
						height: 160px;
					}

					.client-logo-stage {
						height: 100%;
					}

					.client-logo-item {
						height: var(--logo-height, 64px);
					}
				}

				@media (hover: none), (pointer: coarse) {
					.client-logo-viewport,
					.client-logo-item {
						cursor: auto;
					}

					.client-logo-section.is-logo-dragging .client-logo-viewport,
					.client-logo-section.is-logo-dragging .client-logo-track,
					.client-logo-section.is-logo-dragging .client-logo-item {
						cursor: auto !important;
					}
				}

				@media (prefers-reduced-motion: reduce) {
					.client-logo-noise {
						animation: none;
					}
				}
			`}</style>

			<div className="client-logo-stage">
				<div className="client-logo-dither" aria-hidden="true" />
				<div className="client-logo-noise" aria-hidden="true" />
				<div ref={viewportRef} className="client-logo-viewport" aria-label="Client logos">
					<div ref={trackRef} className="client-logo-track">
						<div ref={firstSetRef} className="client-logo-set">
							{logosWithAsset.map((logo) => (
								<div
									key={logo.name}
									className="client-logo-item"
									style={{
										"--logo-scale": String(logo.visualScale ?? 1),
										"--logo-height": `${logo.logoHeight ?? 64}px`
									} as Record<string, string>}
								>
									<div aria-hidden="true" dangerouslySetInnerHTML={{ __html: logo.svg }} />
								</div>
							))}
						</div>
						<div className="client-logo-set" aria-hidden="true">
							{duplicatedLogos.slice(logosWithAsset.length).map((logo, index) => (
								<div
									key={`${logo.name}-${index}`}
									className="client-logo-item"
									style={{
										"--logo-scale": String(logo.visualScale ?? 1),
										"--logo-height": `${logo.logoHeight ?? 64}px`
									} as Record<string, string>}
								>
									<div aria-hidden="true" dangerouslySetInnerHTML={{ __html: logo.svg }} />
								</div>
							))}
						</div>
					</div>
				</div>
				<div className="client-logo-mask" aria-hidden="true" />
			</div>
		</section>
	);
}
